import AstronomyKit
import Foundation

let observer = Observer(latitude: 51.5, longitude: -0.12, height: 46)
let clock = ContinuousClock()
let count = 10_000
var checksum = 0.0
for index in 0..<100 {
    checksum += try Sun.altitudeObservation(universalTime: 9000 + Double(index) / 1440, from: observer, deltaTModel: .espenakMeeus).altitude
}
for trial in 0..<5 {
    let duration = try clock.measure {
        for index in 0..<count {
            checksum += try Sun.altitudeObservation(universalTime: 9000 + Double(index) / 1440, from: observer, deltaTModel: .espenakMeeus).altitude
        }
    }
    let seconds = Double(duration.components.seconds) + Double(duration.components.attoseconds) / 1e18
    print("trial=\(trial) calls=\(count) elapsedSeconds=\(seconds) nanosecondsPerCall=\(seconds * 1e9 / Double(count))")
}
print("checksum=\(checksum)")
